typedef float rational_t;
extern "C" float sqrtf(float);
const rational_t SMALL_DIST = 0.00001f;

inline rational_t fast_recip_sqrt(rational_t x)
{
  return 1.0F/(rational_t)sqrtf(x);
}

class vector3d
{
public:
  typedef rational_t T;
  T x,y,z;

  inline vector3d() {}
  inline vector3d(const vector3d& v) { x = v.x; y = v.y; z = v.z; }
  inline vector3d(T _x, T _y, T _z) { x = _x; y = _y; z = _z; }
  inline vector3d& operator = (const vector3d& v)
  { x = v.x; y = v.y; z = v.z; return *this; }
  inline vector3d& operator *= (T d)
  { x *= d; y *= d; z *= d; return *this; }
  inline T length2() const
  { return x*x + y*y + z*z; }
  inline vector3d& normalize()
  {
    T l2 = length2();
    if (l2>SMALL_DIST*SMALL_DIST)
      *this *= fast_recip_sqrt(l2);
    return *this;
  }
};

inline vector3d operator + (const vector3d& a, const vector3d& b)
{ return vector3d(a.x + b.x, a.y + b.y, a.z + b.z); }
inline vector3d operator - (const vector3d& a, const vector3d& b)
{ return vector3d(a.x - b.x, a.y - b.y, a.z - b.z); }
inline vector3d operator * (const vector3d& a, vector3d::T d)
{ return vector3d(d * a.x, d * a.y, d * a.z); }
inline vector3d operator / (const vector3d& a, vector3d::T d)
{
  vector3d::T d_inv = 1.0f/d;
  return vector3d(a.x*d_inv, a.y*d_inv, a.z*d_inv);
}
inline vector3d::T dot(const vector3d& a, const vector3d& b)
{ return a.x*b.x + a.y*b.y + a.z*b.z; }

class collision_geometry { char data[12]; };
class capsule
{
public:
  vector3d base;
  vector3d end;
  rational_t radius;
};
class collision_capsule : public collision_geometry
{
public:
  void get_closest_point_along_dir(vector3d* target, const vector3d& axis) const;
private:
  capsule rel_cap;
  capsule abs_cap;
  vector3d lag_point;
};

void collision_capsule::get_closest_point_along_dir( vector3d* target, const vector3d& axis ) const
{
  vector3d outval;
  rational_t a = dot(abs_cap.base,axis);
  rational_t b = dot(abs_cap.end,axis);
  vector3d normal_axis = axis;
  normal_axis.normalize();
  if (a<b)
  {
    outval = abs_cap.base-normal_axis*rel_cap.radius;
  }
  else if (b<a)
  {
    outval = abs_cap.end-normal_axis*rel_cap.radius;
  }
  else
  {
    outval = (abs_cap.end+abs_cap.base)/2 - normal_axis*rel_cap.radius;
  }
  *target=outval;
}
